874:                     }
875:                     if(DEBUG_TRACE) {
876:                         logout.println("<< [al "+buffers[i]+", q "+releasedBuffer.alBuffer+"] <- "+getPerfString()+" @ "+getThreadName());
877:                     }
878:                 }
879:             }
880:             if( DEBUG ) {
